('node-13-1', 'phase-13-lesson-01-track-a-micro-frontends-module-federation', 'module-14', 1, 'Lesson 14.1: Track A: Micro-Frontends & Module Federation at Enterprise Scale', 'Prerequisites: Phase 6, Lesson 6.16', 'Prerequisites: Phase 6, Lesson 6.16 | Subtopics: 6 items', 'Systems project application', 360, 14, 3310.0, 50.0, '# Lesson 13.1: Track A: Micro-Frontends & Module Federation at Enterprise Scale

